# Study 2, Chen's home turf: data generated by Chen et al.'s own process, then estimated by their grid matching.
# Each simulated person has true (r, d) drawn uniformly from the grid with r < 1 and d < 1 (400 pairs). On item j the person is
# correct with probability 1 - eps if spreadr (Chen's settings, chen_S.npz, S_any) activates the solution under (r, d), else eps.
# Trials missing with probability .02. Estimation: Chen's rules (match share, duration tie-breaker), as in chen_apply.py.
# Factors: eps in {.05, .15, .25} x N in {50, 100}; 1,000 datasets each. Network: SWOW-EN18 (Chen's own networks pending item key).
# Output: out/s2/home_results.csv (one row per dataset) and logs/sim_chen_home.txt (summary).
import numpy as np, pandas as pd, os
from scipy.stats import spearmanr
Z = np.load('../05_Chen对比/chen_S.npz'); S = Z['S_any'].astype(float); DUR = Z['dur'] * Z['S_any']; combos = Z['combos']; J = S.shape[1]
pool = np.flatnonzero((combos[:, 0] < 1) & (combos[:, 1] < 1)); pat = {tuple(S[k]) for k in pool}
pid = {p: i for i, p in enumerate(sorted(pat))}; patidx = np.array([pid.get(tuple(s), -1) for s in S])
def est(corr, obs):
    n = obs.sum(1, keepdims=True); agree = (corr * obs) @ S.T + ((1 - corr) * obs) @ (1 - S).T
    acc = agree / np.maximum(n, 1); best = np.isclose(acc, acc.max(1, keepdims=True))
    return np.argmax(np.where(best, obs @ DUR.T, -1), 1)
def cr(a, b):
    return np.nan if np.std(a) == 0 or np.std(b) == 0 else spearmanr(a, b)[0]
rows = []
for c, (eps, N) in enumerate([(e, n) for e in (.05, .15, .25) for n in (50, 100)]):
    for rep in range(1000):
        rng = np.random.default_rng(np.random.SeedSequence([2, c, rep]))
        tk = rng.choice(pool, N); p = np.where(S[tk] == 1, 1 - eps, eps)
        corr = (rng.random((N, J)) < p).astype(float); obs = (rng.random((N, J)) >= .02).astype(float)
        ek = est(corr, obs)
        rows.append(dict(cell=c, eps=eps, N=N, rep=rep,
                         r_r=cr(combos[tk, 0], combos[ek, 0]), r_d=cr(combos[tk, 1], combos[ek, 1]),
                         exact=np.mean(ek == tk), same_pattern=np.mean(patidx[ek] == patidx[tk]),
                         n_est=len(set(ek)), acc_r=cr(corr.sum(1) / obs.sum(1), combos[ek, 0])))
os.makedirs('out/s2', exist_ok=True); res = pd.DataFrame(rows); res.to_csv('out/s2/home_results.csv', index=False)
print(f'SWOW-EN18: {len(pat)} distinct success patterns among the 400 generating (r, d) pairs')
print('Medians over 1,000 datasets per cell (Spearman r between true and estimated parameter):')
print(res.groupby(['eps', 'N'])[['r_r', 'r_d', 'exact', 'same_pattern', 'n_est', 'acc_r']].median().round(3).to_string())
